/** Device config for internal user auto login. Only one config per device is stored. */
export class DeviceConfig implements CredentialsStorage, UsageTestStorage {
	static readonly Version = 3
	static readonly LocalStorageKey = "tutanotaConfig"

	private config: Config

	constructor(private readonly version: number = DeviceConfig.Version, private readonly storage: Storage | null = getLocalStorage()) {
		this.config = this.defaultConfig()
		this._load()
	}

	private defaultConfig(): Config {
		return {
			_version: this.version,
			_credentials: new Map(),
			_scheduledAlarmUsers: [],
			_themeId: defaultThemeId,
			_language: null,
			_defaultCalendarView: {},
			_hiddenCalendars: {},
			_signupToken: "",
			_credentialEncryptionMode: null,
			_encryptedCredentialsKey: null,
			_testDeviceId: null,
			_testAssignments: null,
		}
	}

	store(persistentCredentials: PersistentCredentials): void {

		const existing = this.config._credentials.get(persistentCredentials.credentialInfo.userId)

		if (existing?.databaseKey) {
			persistentCredentials.databaseKey = existing.databaseKey
		}

		if (JSON.stringify(existing) !== JSON.stringify(persistentCredentials)) {
			this.config._credentials.set(persistentCredentials.credentialInfo.userId, persistentCredentials)
			this._writeToStorage()
		}
	}

	loadByUserId(userId: Id): PersistentCredentials | null {
		return this.config._credentials.get(userId) ?? null
	}

	loadAll(): Array<PersistentCredentials> {
		return Array.from(this.config._credentials.values())
	}

	deleteByUserId(userId: Id): void {
		if (this.config._credentials.delete(userId)) this._writeToStorage()
	}

	_load(): void {
		let loadedConfig: any = null
		try {
			const stored = this.storage?.getItem(DeviceConfig.LocalStorageKey)
			loadedConfig = stored == null ? null : this._parseConfig(stored)
		} catch (e) {
			console.warn("Could not read device config", e)
		}

		if (loadedConfig && (typeof loadedConfig !== "object" || Array.isArray(loadedConfig))) {
			loadedConfig = null
		}

		const needsMigration = loadedConfig != null && loadedConfig._version !== this.version
		if (needsMigration) {
			migrateConfig(loadedConfig, this.version)
		}

		const defaults = this.defaultConfig()
		if (loadedConfig) {
			const credentials = loadedConfig._credentials
			this.config = {
				_version: this.version,
				_credentials: new Map(credentials && typeof credentials === "object" && !Array.isArray(credentials) ? Object.entries(credentials) : []),
				_scheduledAlarmUsers: loadedConfig._scheduledAlarmUsers ?? defaults._scheduledAlarmUsers,
				_themeId: loadedConfig._themeId ?? defaults._themeId,
				_language: loadedConfig._language ?? defaults._language,
				_defaultCalendarView: loadedConfig._defaultCalendarView ?? defaults._defaultCalendarView,
				_hiddenCalendars: loadedConfig._hiddenCalendars ?? defaults._hiddenCalendars,
				_signupToken: loadedConfig._signupToken ?? defaults._signupToken,
				_credentialEncryptionMode: loadedConfig._credentialEncryptionMode ?? defaults._credentialEncryptionMode,
				_encryptedCredentialsKey: loadedConfig._encryptedCredentialsKey ?? defaults._encryptedCredentialsKey,
				_testDeviceId: loadedConfig._testDeviceId ?? defaults._testDeviceId,
				_testAssignments: loadedConfig._testAssignments ?? defaults._testAssignments,
			}
		}

		const needsToken = !this.config._signupToken
		if (needsToken) {
			const bytes = new Uint8Array(6)
			// Crypto may be absent in a test or non-browser context.
			if (typeof crypto !== "undefined" && crypto.getRandomValues) {
				crypto.getRandomValues(bytes)
			} else {
				for (let i = 0; i < bytes.length; i++) bytes[i] = Math.floor(Math.random() * 256)
			}
			this.config._signupToken = uint8ArrayToBase64(bytes)
		}
		if (needsMigration || needsToken) this._writeToStorage()
	}

	_parseConfig(loadedConfigString: string): any | null {
		try {
			return JSON.parse(loadedConfigString)
		} catch (e) {
			console.warn("Could not parse device config")
			return null
		}
	}

	getSignupToken(): string {
		return this.config._signupToken
	}

	hasScheduledAlarmsForUser(userId: Id): boolean {
		return this.config._scheduledAlarmUsers.includes(userId)
	}

	setAlarmsScheduledForUser(userId: Id, setScheduled: boolean) {
		const scheduledIndex = this.config._scheduledAlarmUsers.indexOf(userId)

		const scheduledSaved = scheduledIndex !== -1

		if (setScheduled && !scheduledSaved) {
			this.config._scheduledAlarmUsers.push(userId)
			this._writeToStorage()
		} else if (!setScheduled && scheduledSaved) {
			this.config._scheduledAlarmUsers.splice(scheduledIndex, 1)
			this._writeToStorage()
		}
	}

	setNoAlarmsScheduled() {
		if (this.config._scheduledAlarmUsers.length) {
			this.config._scheduledAlarmUsers = []
			this._writeToStorage()
		}
	}

	getLanguage(): LanguageCode | null {
		return this.config._language
	}

	setLanguage(language: LanguageCode | null) {
		if (this.config._language !== language) {
			this.config._language = language
			this._writeToStorage()
		}
	}

	_writeToStorage() {
		try {
			this.storage?.setItem(DeviceConfig.LocalStorageKey, JSON.stringify({
				...this.config,
				_credentials: Object.fromEntries(this.config._credentials),
			}))
		} catch (e) {
			console.log("could not store config", e)
		}
	}

	getTheme(): ThemeId {
		return this.config._themeId
	}

	setTheme(theme: ThemeId) {
		if (this.config._themeId !== theme) {
			this.config._themeId = theme

			this._writeToStorage()
		}
	}

	getDefaultCalendarView(userId: Id): CalendarViewType | null {
		return this.config._defaultCalendarView                [userId]
	}

	setDefaultCalendarView(userId: Id, defaultView: CalendarViewType) {
		if (this.config._defaultCalendarView[userId] !== defaultView) {
			this.config._defaultCalendarView[userId] = defaultView

			this._writeToStorage()
		}
	}

	getHiddenCalendars(user: Id): Id[] {
		return this.config._hiddenCalendars.hasOwnProperty(user) ? this.config._hiddenCalendars[user] : []
	}

	setHiddenCalendars(user: Id, calendars: Id[]) {
		if (JSON.stringify(this.config._hiddenCalendars[user]) !== JSON.stringify(calendars)) {
			this.config._hiddenCalendars[user] = calendars

			this._writeToStorage()
		}
	}

	getCredentialEncryptionMode(): CredentialEncryptionMode | null {
		return this.config._credentialEncryptionMode
	}

	setCredentialEncryptionMode(encryptionMode: CredentialEncryptionMode | null) {
		if (this.config._credentialEncryptionMode !== encryptionMode) {
			this.config._credentialEncryptionMode = encryptionMode
			this._writeToStorage()
		}
	}

	getCredentialsEncryptionKey(): Uint8Array | null {
		return this.config._encryptedCredentialsKey ? base64ToUint8Array(this.config._encryptedCredentialsKey) : null
	}

	setCredentialsEncryptionKey(value: Uint8Array | null) {
