export function migrateConfig(loadedConfig: any, version: number = DeviceConfig.Version) {
	if (loadedConfig._version === version) return
	if (loadedConfig._version < 3) {
		migrateConfigV2to3(loadedConfig)
	}
	loadedConfig._version = version
}

/** Migrate V2 array credentials to a userId-keyed object. */
export function migrateConfigV2to3(loadedConfig: any) {
	if (!Array.isArray(loadedConfig._credentials)) return
	const credentials: Record<string, PersistentCredentials> = {}
	for (const oldCredential of loadedConfig._credentials) {
		if (!oldCredential || !oldCredential.userId) continue
		const internal = typeof oldCredential.mailAddress === "string" && oldCredential.mailAddress.includes("@")
		credentials[oldCredential.userId] = {
			credentialInfo: {
				login: internal ? oldCredential.mailAddress : oldCredential.userId,
				userId: oldCredential.userId,
				type: internal ? "internal" : "external",
			},
			encryptedPassword: oldCredential.encryptedPassword,
			accessToken: oldCredential.accessToken,
			databaseKey: oldCredential.databaseKey ?? null,
		}
	}
	loadedConfig._credentials = credentials
}

