import {DeviceConfig, migrateConfigV2to3} from "../../../src/misc/DeviceConfig"
import {PersistentCredentials} from "../../../src/misc/credentials/CredentialsProvider"

o.spec("DeviceConfig", function () {
	o.spec("migrateConfig", function () {
		o("migrating from v2 to v3 preserves internal logins", function () {
			const oldConfig: any = {
				_version: 2,
				_credentials: [
					{
						mailAddress: "internal@example.com",
						userId: "internalUserId",
						accessToken: "internalAccessToken",
						encryptedPassword: "internalEncPassword",
					},
					{
						mailAddress: "externalUserId",
						userId: "externalUserId",
						accessToken: "externalAccessToken",
						encryptedPassword: "externalEncPassword",
					databaseKey: null,
					},
				],
			}

			migrateConfigV2to3(oldConfig)

			const expectedCredentialsAfterMigration: Record<string, Omit<PersistentCredentials, "databaseKey"> & {databaseKey: null}> = {
				internalUserId: {
					credentialInfo: {
						login: "internal@example.com",
						userId: "internalUserId",
						type: "internal"
					},
					accessToken: "internalAccessToken",
					encryptedPassword: "internalEncPassword",
					databaseKey: null
				},
				externalUserId: {
					credentialInfo: {
						login: "externalUserId",
						userId: "externalUserId",
						type: "external",
					},
					accessToken: "externalAccessToken",
					encryptedPassword: "externalEncPassword",
					databaseKey: null,
				}
			}

			o(oldConfig._credentials).deepEquals(expectedCredentialsAfterMigration)
		})
	})
	o("loads current config without writing and retains every field", function () {
		const stored = {
			_version: DeviceConfig.Version,
			_credentials: {user: {credentialInfo: {userId: "user", login: "user@example.com", type: "internal"}, accessToken: "token", encryptedPassword: "password", databaseKey: "key"}},
			_scheduledAlarmUsers: ["user"], _themeId: "dark", _language: "en",
			_defaultCalendarView: {user: "month"}, _hiddenCalendars: {user: ["calendar"]},
			_signupToken: "existing", _credentialEncryptionMode: null, _encryptedCredentialsKey: "abc",
			_testDeviceId: "device", _testAssignments: {assignment: "value"},
		}
		let writes = 0
		const storage = {
			getItem: () => JSON.stringify(stored),
			setItem: () => { writes++ },
		} as unknown as Storage
		const config = new DeviceConfig(DeviceConfig.Version, storage)
		o(writes).equals(0)
		o(config.loadByUserId("user")?.databaseKey).equals("key")
		o(config.getSignupToken()).equals("existing")
		config.setTheme("light")
		o(writes).equals(1)
	})

